package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcAssessmentSnapshotsTest extends JdbcAssessmentPoliciesTest {
 AssessmentSnapshots snapshots;Instant start,end;String period;long policyId;
 @BeforeEach void snapshots(){jdbc.execute("DROP TRIGGER IF EXISTS fail_assessment_month_audit");for(String t:List.of("assessment_snapshot_fact","assessment_snapshot","assessment_month","invite_phone_evidence","invite_registration","invite_code","coupon_transaction_event","order_coupon_allocation","coupon_service_redemption","refund_event","refund","payment_event","payment_exception","payment","order_redemption","order_status_transition","service_evidence_file","service_report_submission","technician_assignment","technician_report","repair_protection","pickup_check","file_object","order"))jdbc.update("DELETE FROM `"+t+"`");var manager=new DataSourceTransactionManager(jdbc.getDataSource());snapshots=new AssessmentSnapshots(db,new OperatorIdentity(jdbc,null,manager),policies,manager);}
 void prepare(){prepare(false);}
 void prepare(boolean all){start=month(1);end=month(2);period=start.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString().substring(0,7);var b=config(1).put("acquisition_target",2).put("coupon_target",2);var required=b.putArray("process_requirements").add("CHECK_IN_CONFIRMED");if(all)required.add("PROTECTION_COMPLETE").add("REPORT_SUBMITTED").add("QUALITY_SIGNED");policyId=policies.create(operator,key(),b).path("data").path("id").asLong();activate(policyId);clock.value=start.plusSeconds(100);}
 ObjectNode request(long revision){return json.createObjectNode().put("merchant_id",1).put("period_month",period).put("expected_revision",revision);}
 JsonNode settle(long revision){clock.value=end;return snapshots.create(operator,key(),request(revision)).path("data");}
 void formalOrder(long id,Instant at,boolean confirmed){jdbc.update("INSERT INTO `order`(id,order_no,user_id,vehicle_id,merchant_id,project_id,amount,pay_amount,status,created_at,check_in_completed_at,owner_confirmed_at) VALUES(?,?,1,1,1,1,10,10,'COMPLETED',?,?,?)",id,"synthetic-"+id,ReservationStore.time(at.minusSeconds(60)),confirmed?ReservationStore.time(at.minusSeconds(20)):null,confirmed?ReservationStore.time(at.minusSeconds(10)):null);jdbc.update("INSERT INTO payment(id,order_id,channel,channel_payment_no,payment_no,amount,status,paid_at) VALUES(?,?,'WECHAT',?,?,10,'SUCCEEDED',?)",id,id,"synthetic-channel-"+id,"synthetic-payment-"+id,ReservationStore.time(at.minusSeconds(30)));jdbc.update("INSERT INTO payment_event(channel,event_id,payment_id,event_hash,outcome,created_at) VALUES('WECHAT',?,?,?,'PAID',?)",key(),id,"a".repeat(64),ReservationStore.time(at.minusSeconds(30)));jdbc.update("INSERT INTO order_redemption(order_id,merchant_id,staff_id,payment_id,test_mode,redeemed_at) VALUES(?,1,1,?,0,?)",id,id,ReservationStore.time(at));jdbc.update("INSERT INTO order_status_transition(order_id,merchant_id,from_status,to_status,action,actor_type,actor_id,occurred_at) VALUES(?,1,'PENDING_VERIFY','COMPLETED','ORDER_COMPLETE','staff_account',1,?)",id,ReservationStore.time(at));if(confirmed)jdbc.update("INSERT INTO pickup_check(order_id,merchant_id,staff_id,owner_confirm,confirm_at) VALUES(?,1,1,1,?)",id,ReservationStore.time(at.minusSeconds(10)));}
 void invitation(String identity){jdbc.update("INSERT INTO invite_code(id,code,actor_type,actor_id,merchant_id,created_at) VALUES(10,?,'staff_account',1,1,?)","a".repeat(32),ReservationStore.time(start));jdbc.update("INSERT INTO invite_registration(user_id,record_id,app_id,identity_source,invite_code_id,source_type,source_id,merchant_id,attribution_result,qualification_status,registered_at,qualified_at,reward_month,rule_version) VALUES(1,?,'synthetic-app',?,10,'staff_account',1,1,'ATTRIBUTED','QUALIFIED',?,?,?,'R6A_INVITE_V1')",key(),identity,ReservationStore.time(start.plusSeconds(1)),ReservationStore.time(start.plusSeconds(2)),period);jdbc.update("INSERT INTO invite_phone_evidence(phone_hash,user_id,app_id,verified_at) VALUES(?,1,'synthetic-app',?)","b".repeat(64),ReservationStore.time(start.plusSeconds(2)));}
 long coupon(String kind){var b=draft(10);((ObjectNode)b.get("terms")).put("valid_to",end.plusSeconds(86400).toString());if(kind.equals("SERVICE"))((ObjectNode)b.get("terms")).put("type","SERVICE").put("amount","0.00").put("min_spend","0.00");long id=coupons.create(merchant,key(),b).path("data").path("coupon_id").asLong();coupons.status(merchant,id,key(),statusBody(1,"PUBLISHED"));return coupons.claim(owner,key(),claimBody(id)).path("data").path("user_coupon_id").asLong();}
 void service(long uc){var r=jdbc.queryForMap("SELECT i.*,p.terms_json FROM coupon_issue i JOIN coupon_publication p ON p.coupon_id=i.coupon_id AND p.revision=i.publication_revision WHERE i.user_coupon_id=?",uc);long id=db.insert("INSERT INTO coupon_service_redemption(user_coupon_id,user_id,coupon_id,publication_revision,merchant_id,project_id,staff_id,authorization_revision,terms_json,redeemed_at,rule_version) VALUES(?,1,?,?,1,1,1,1,?,?,'R5B_SERVICE_V1')",uc,r.get("coupon_id"),r.get("publication_revision"),r.get("terms_json").toString(),ReservationStore.time(start.plusSeconds(200)));jdbc.update("INSERT INTO coupon_transaction_event(user_coupon_id,event_key,kind,redemption_id,before_status,after_status,rule_version,occurred_at) VALUES(?,?,'SERVICE_REDEEM',?,'AVAILABLE','USED','R5B_SERVICE_V1',?)",uc,"synthetic-service-"+id,id,ReservationStore.time(start.plusSeconds(200)));}
 void cash(long order,long uc){var r=jdbc.queryForMap("SELECT i.*,p.terms_json FROM coupon_issue i JOIN coupon_publication p ON p.coupon_id=i.coupon_id AND p.revision=i.publication_revision WHERE i.user_coupon_id=?",uc);jdbc.update("UPDATE `order` SET coupon_id=?,amount=15 WHERE id=?",r.get("coupon_id"),order);jdbc.update("INSERT INTO order_coupon_allocation(order_id,creation_key,request_digest,user_coupon_id,user_id,coupon_id,publication_revision,merchant_id,project_id,terms_json,original_amount,discount_amount,cash_amount,state,reserved_until,rule_version,created_at,updated_at) VALUES(?,?,?, ?,1,?,?,1,1,?,15,5,10,'CONSUMED',?,'R5B_CASH_V1',?,?)",order,key(),"c".repeat(64),uc,r.get("coupon_id"),r.get("publication_revision"),r.get("terms_json").toString(),ReservationStore.time(end),ReservationStore.time(start),ReservationStore.time(start));jdbc.update("INSERT INTO coupon_transaction_event(user_coupon_id,event_key,kind,order_id,payment_id,before_status,after_status,rule_version,occurred_at) VALUES(?,?,'CONSUME',?,?,'AVAILABLE','USED','R5B_CASH_V1',?)",uc,"synthetic-consume-"+order,order,order,ReservationStore.time(start.plusSeconds(30)));}
 @Test void noPolicyIsUnknownAndLegacyScoresNeverImported(){period="2026-01";clock.value=Instant.parse("2026-02-01T00:00:00Z");jdbc.update("INSERT INTO assessment(merchant_id,period_month,total_score,grade) VALUES(1,'2026-01-01',99,'LEGACY')");var r=snapshots.create(operator,key(),request(0)).path("data");assertEquals("UNKNOWN",r.path("summary").path("state").asText());assertTrue(r.path("policy").isNull());assertEquals(0,count("assessment_snapshot_fact"));assertFalse(r.toString().contains("LEGACY"));}
 @Test void mixedKnownFactsProduceRoundedGradeAndRecomputeFromStoredFacts(){prepare();formalOrder(10,start.plusSeconds(1000),true);formalOrder(11,start.plusSeconds(1001),false);invitation("VERIFIED_WECHAT");service(coupon("SERVICE"));cash(10,coupon("DISCOUNT"));var r=settle(0);assertEquals("70.00",r.path("summary").path("total_score").asText());assertEquals("B",r.path("summary").path("grade").path("code").asText());long id=r.path("id").asLong();var facts=new ArrayList<Map<String,Object>>();for(var row:jdbc.queryForList("SELECT fact_json FROM assessment_snapshot_fact WHERE snapshot_id=? ORDER BY ordinal",id))facts.add(json.convertValue(db.parse(row.get("fact_json")),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){}));assertEquals(r.path("summary"),db.parse(db.json(AssessmentCalculation.summary(r.path("policy"),facts))));assertEquals(1,r.path("summary").path("metrics").path("acquisition").path("numerator").asInt());assertEquals(5,facts.size());assertFalse(db.json(facts).contains("synthetic-app"));assertFalse(db.json(facts).contains("phone_hash"));}
 @Test void nextMonthOnlyAndBeijingExclusiveEnd(){prepare();assertEquals(409,code(()->snapshots.create(operator,key(),request(0))));formalOrder(10,end.minusSeconds(1),true);formalOrder(11,end,true);var r=settle(0);assertEquals(1,r.path("summary").path("metrics").path("process").path("denominator").asInt());assertEquals("20.00",r.path("summary").path("total_score").asText());}
 @Test void stopMustProveWholeMonthAndOldStoppedDateIsNeverGuessed(){prepare();policies.status(operator,policyId,key(),statusBody(2,"STOPPED"));assertNotNull(jdbc.queryForObject("SELECT stopped_at FROM assessment_policy WHERE id=?",java.sql.Timestamp.class,policyId));assertTrue(settle(0).path("policy").isNull());jdbc.update("UPDATE assessment_policy SET stopped_at=? WHERE id=?",ReservationStore.time(end),policyId);formalOrder(10,start.plusSeconds(1000),true);assertFalse(settle(1).path("policy").isNull());jdbc.update("UPDATE assessment_policy SET stopped_at=NULL WHERE id=?",policyId);assertTrue(settle(2).path("policy").isNull());}
 @Test void fullRefundCreatesNewRevisionAndKeepsOriginalUseMonthSnapshot(){prepare();formalOrder(10,start.plusSeconds(1000),true);long uc=coupon("DISCOUNT");cash(10,uc);var first=settle(0);assertEquals(1,first.path("summary").path("metrics").path("coupon").path("numerator").asInt());jdbc.update("UPDATE `order` SET status='CLOSED',close_reason='REFUND_CANCELLED' WHERE id=10");long refund=db.insert("INSERT INTO refund(order_id,payment_id,amount,status,refunded_at,owner_consented_at,merchant_consented_at,refund_no,channel_refund_no,from_status) VALUES(10,10,10,'SUCCEEDED',?,?,?,'Raaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','synthetic-refund','COMPLETED')",ReservationStore.time(end.plusSeconds(60)),ReservationStore.time(end),ReservationStore.time(end));jdbc.update("INSERT INTO refund_event(channel,event_id,refund_id,event_hash,outcome) VALUES('WECHAT',?,?,?,'SUCCEEDED')",key(),refund,"d".repeat(64));jdbc.update("UPDATE order_coupon_allocation SET state='RETURNED' WHERE order_id=10");jdbc.update("INSERT INTO coupon_transaction_event(user_coupon_id,event_key,kind,order_id,payment_id,refund_id,before_status,after_status,rule_version,occurred_at) VALUES(?,'synthetic-return','REFUND_RETURN',10,10,?,'USED','AVAILABLE','R5B_CASH_V1',?)",uc,refund,ReservationStore.time(end.plusSeconds(60)));clock.value=end.plusSeconds(100);var next=snapshots.create(operator,key(),request(1)).path("data");assertEquals(0,next.path("summary").path("metrics").path("coupon").path("numerator").asInt());assertEquals(1,next.path("summary").path("metrics").path("process").path("denominator").asInt());assertEquals(first,db.parse(db.json(snapshots.detail(operator,first.path("id").asLong()))));assertNotEquals(first.path("facts_hash"),next.path("facts_hash"));}
 @Test void testAndUnverifiableCompletionDoNotBecomeFormalGrades(){prepare();formalOrder(10,start.plusSeconds(1000),true);jdbc.update("UPDATE payment SET channel='LOCAL_TEST' WHERE id=10");jdbc.update("UPDATE order_redemption SET test_mode=1 WHERE order_id=10");var r=settle(0);assertTrue(r.path("summary").path("total_score").isNull());assertEquals(0,r.path("summary").path("metrics").path("process").path("denominator").asInt());jdbc.update("UPDATE payment SET channel='WECHAT' WHERE id=10");jdbc.update("UPDATE order_redemption SET test_mode=0 WHERE order_id=10");jdbc.update("DELETE FROM payment_event");assertTrue(settle(1).path("summary").path("total_score").isNull());}
 @Test void missingRequiredEvidenceIsNotASourceFailure(){prepare();formalOrder(10,start.plusSeconds(1000),false);var r=settle(0);assertEquals("0.00",r.path("summary").path("total_score").asText());assertEquals("B",r.path("summary").path("grade").path("code").asText());}
 @Test void legacyCompletionAndServiceIdentityUnknownBlockTheirDimensions(){prepare();formalOrder(10,start.plusSeconds(1000),true);service(coupon("SERVICE"));assertTrue(settle(0).path("summary").path("metrics").path("coupon").path("score").isNull());jdbc.update("DELETE FROM order_redemption");assertTrue(settle(1).path("summary").path("metrics").path("process").path("score").isNull());}
 @Test void permanentReceiptReauthorizesAndCannotChangeBodyAfterExpiry(){prepare();String k=key();clock.value=end;var b=request(0);var first=snapshots.create(operator,k,b);snapshots.create(operator,key(),request(1));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(first.path("data"),snapshots.create(operator,k,b).path("data"));assertEquals(400,code(()->snapshots.create(operator,k,b.deepCopy().put("expected_revision",2))));jdbc.update("UPDATE operator_account SET can_assessment=0,can_points=1 WHERE id=1");assertEquals(403,code(()->snapshots.create(operator,k,b)));assertEquals(403,code(()->snapshots.list(operator,1)));assertEquals(403,code(()->snapshots.facts(operator,first.path("data").path("id").asLong(),1)));}
 @Test void auditFailureRollsBackHeadRevisionFactsAndOriginalKeyCanRetry(){prepare();formalOrder(10,start.plusSeconds(1000),true);clock.value=end;jdbc.execute("CREATE TRIGGER fail_assessment_month_audit BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic rollback'");String k=key();assertEquals(503,code(()->snapshots.create(operator,k,request(0))));assertEquals(0,count("assessment_snapshot"));assertEquals(0,count("assessment_month"));assertEquals(0,count("assessment_snapshot_fact"));jdbc.execute("DROP TRIGGER fail_assessment_month_audit");assertEquals(1,snapshots.create(operator,k,request(0)).path("data").path("revision").asInt());}
 @Test void concurrentOperatorsHaveOneCasWinnerAndOtherStoreIsIndependent()throws Exception{prepare();clock.value=end;jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_assessment) VALUES(2,'monthly-peer','unused','13800000001',1)");var peerOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(600));var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var tasks=new ArrayList<Future<Integer>>();for(var op:List.of(operator,peerOp))tasks.add(pool.submit(()->{gate.await();try{snapshots.create(op,key(),request(0));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}}));gate.countDown();var codes=new ArrayList<Integer>();for(var f:tasks)codes.add(f.get(30,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes);}finally{pool.shutdownNow();}assertEquals(1,count("assessment_snapshot"));assertEquals(1,snapshots.create(operator,key(),request(0).put("merchant_id",2)).path("data").path("revision").asInt());}
 void evidence(){
  jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account,status) VALUES(3,1,'TECHNICIAN','synthetic-month-tech','ACTIVE')");
  jdbc.update("UPDATE `order` SET assigned_at=?,service_report_ready_at=? WHERE id=10",ReservationStore.time(start.plusSeconds(980)),ReservationStore.time(start.plusSeconds(996)));
  jdbc.update("INSERT INTO technician_assignment(order_id,merchant_id,technician_id,status,assigned_by,accepted_at) VALUES(10,1,3,'ACCEPTED',1,?)",ReservationStore.time(start.plusSeconds(990)));
  for(int id=100;id<=103;id++)jdbc.update("INSERT INTO file_object(id,owner_type,owner_id,object_key,content_type,size_bytes,scan_status) VALUES(?,'staff_account',?,?,'image/png',100,'CLEAN')",id,id==100?1:3,"synthetic-month-file-"+id);
  jdbc.update("INSERT INTO repair_protection(id,order_id,items,uploaded_at) VALUES(1,10,'[\"SEAT_COVER\",\"STEERING_COVER\"]',?)",ReservationStore.time(start.plusSeconds(985)));
  jdbc.update("INSERT INTO technician_report(id,order_id,technician_id,process_photos,fault_part_photos,finish_photos,repair_plan,fault_analysis,parts_used,work_hours,status,signed_at) VALUES(1,10,3,'[101]','[]','[102]','合成施工方案','合成故障分析','[]',10,1,?)",ReservationStore.time(start.plusSeconds(996)));
  jdbc.update("INSERT INTO service_report_submission(order_id,report_id,no_fault_parts,no_parts,submitted_at) VALUES(10,1,1,1,?)",ReservationStore.time(start.plusSeconds(995)));
  for(var e:Map.of(100,"PROTECTION",101,"PROCESS",102,"FINISH",103,"SIGNATURE").entrySet())jdbc.update("INSERT INTO service_evidence_file(order_id,record_id,file_id,kind) VALUES(10,1,?,?)",e.getKey(),e.getValue());
 }
 @Test void allFourEvidenceTypesAreVerifiedAndChangedPrivateFileCreatesUnknownRevision(){prepare(true);formalOrder(10,start.plusSeconds(1000),true);evidence();var first=settle(0);assertEquals("20.00",first.path("summary").path("total_score").asText());jdbc.update("UPDATE file_object SET scan_status='BLOCKED' WHERE id=103");var next=settle(1);assertTrue(next.path("summary").path("total_score").isNull());assertNotEquals(first.path("facts_hash"),next.path("facts_hash"));assertEquals("20.00",db.parse(db.json(snapshots.detail(operator,first.path("id").asLong()))).path("summary").path("total_score").asText());var facts=json.valueToTree(snapshots.facts(operator,next.path("id").asLong(),1));assertEquals("UNKNOWN",facts.path("items").get(0).path("evidence").path("QUALITY_SIGNED").asText());assertFalse(facts.toString().contains("合成施工方案"));assertFalse(facts.toString().contains("synthetic-month-file"));}
 @Test void testInvitationAndServiceAreExcludedButBrokenQualifiedEvidenceIsUnknown(){prepare();formalOrder(10,start.plusSeconds(1000),true);invitation("TEST");service(coupon("SERVICE"));var first=settle(0);assertEquals("20.00",first.path("summary").path("total_score").asText());assertEquals(0,first.path("summary").path("metrics").path("coupon").path("numerator").asInt());jdbc.update("UPDATE invite_registration SET identity_source='VERIFIED_WECHAT'");jdbc.update("DELETE FROM invite_phone_evidence");assertTrue(settle(1).path("summary").path("metrics").path("acquisition").path("score").isNull());}
 @Test void differentStoresCanSettleConcurrentlyWithoutGapLockCycles()throws Exception{prepare();clock.value=end;jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_assessment) VALUES(2,'different-shop-peer','unused','13800000001',1)");var peerOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),Instant.now().plusSeconds(600));var pool=Executors.newFixedThreadPool(2);var gate=new CountDownLatch(1);try{var first=pool.submit(()->{gate.await();return snapshots.create(operator,key(),request(0)).path("data").path("revision").asInt();});var second=pool.submit(()->{gate.await();return snapshots.create(peerOp,key(),request(0).put("merchant_id",2)).path("data").path("revision").asInt();});gate.countDown();assertEquals(1,first.get(30,TimeUnit.SECONDS));assertEquals(1,second.get(30,TimeUnit.SECONDS));}finally{pool.shutdownNow();}assertEquals(2,count("assessment_snapshot"));}

}
